#include <stdio.h>
#include <stdlib.h>

struct Node {
    int value;
    struct Node *next;
};

struct Node *push(struct Node *head, int value) {
    struct Node *node = malloc(sizeof(struct Node));
    node->value = value;
    node->next = head;
    return node;
}

int main() {
    struct Node *list = NULL;
    for (int v = 7; v >= 1; v--) {
        list = push(list, v * 10);
    }
    struct Node *slow = list, *fast = list;
    while (fast != NULL && fast->next != NULL) {
        slow = slow->next;
        fast = fast->next->next;
    }
    printf("%d\n", slow->value);
    return 0;
}
